const hosts = all.filter(([e])=>e.shadowRoot).map(([e,p])=>p+' '+e.tagName.toLowerCase()+(e.id?'#'+e.id:'')+'.'+e.className);
const ins = all.filter(([e])=>e.matches('input,textarea,select')&&e.getRootNode()!==document).map(([e,p])=>({p,type:e.type,id:e.id,ph:e.placeholder,aria:e.getAttribute('aria-label'),lb:e.getAttribute('aria-labelledby'),labels:[...(e.labels||[])].map(l=>l.textContent.trim())}));
