{"function":"() => {
const parse = c => { const m = c.match(/[\d.]+/g).map(Number); return {r:m[0],g:m[1],b:m[2],a:m[3]===undefined?1:m[3]}; };
const lum = ({r,g,b}) => { const f = v => { v/=255; return v<=0.03928? v/12.92 : Math.pow((v+0.055)/1.055,2.4); }; return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b); };
const bgOf = el => { let e = el; while (e) { if (e.nodeType===1) { const c = parse(getComputedStyle(e).backgroundColor); if (c.a>0) return c; } e = e.parentElement || (e.getRootNode && e.getRootNode().host); } return {r:255,g:255,b:255,a:1}; };
const info = el => { const cs = getComputedStyle(el); const fg = parse(cs.color), bg = bgOf(el); const L1=lum(fg), L2=lum(bg); return {t: el.textContent.trim().slice(0,40), color: cs.color, bg:`rgb(${bg.r},${bg.g},${bg.b})`, fs: cs.fontSize, fw: cs.fontWeight, ratio: +( (Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05)).toFixed(2), op: cs.opacity}; };
const out = {};
out.filterTag = info(document.querySelector('pnip-filter-panel .br-tag span.text-gray-50'));
out.status = info(document.querySelector('pnip-status-solicitacao-utils .text-secondary-01'));
out.td = info(document.querySelector('tbody td:nth-child(3)'));
out.th = info(document.querySelector('thead th:nth-child(3)'));
out.upd = info(document.querySelector('table').parentElement.previousElementSibling);
out.h2 = info(document.querySelector('h2'));
out.tabActive = info(document.querySelector('.tab-item.active button .name'));
out.tab = info(document.querySelector('.tab-item:not(.active) button .name'));
// find "Nenhum filtro"
const all=[...document.querySelectorAll('*')].filter(e=>e.childElementCount===0 && /Nenhum filtro/.test(e.textContent));
out.nenhum = all.map(e=>({...info(e), tag:e.tagName, html:e.outerHTML.replace(/ _ng[a-z]+-[a-z0-9-]+=""/g,'').slice(0,300), parent: e.parentElement.outerHTML.replace(/ _ng[a-z]+-[a-z0-9-]+=""/g,'').slice(0,200)}));
out.pag = [...document.querySelectorAll('.br-pagination a.page')].map(a=>({...info(a), cur:a.getAttribute('aria-current'), cls:a.className}));
out.pagInfo = info(document.querySelector('.br-pagination .pagination-information, .br-pagination [class*=information]')||document.body);
return out;
}"}

