{"function":"async () => {
// list tabbable elements in order (approx), deep
const res = [];
const walk = (root) => { for (const el of root.querySelectorAll('*')) { if (el.shadowRoot) walk(el.shadowRoot); if (el.matches('a[href],button,input,select,textarea,[tabindex]') && !el.disabled && el.tabIndex>=0) { const r = el.getBoundingClientRect(); if (r.width>0) res.push(el.tagName+'|'+(el.getAttribute('aria-label')||el.title||el.textContent.trim()).slice(0,30)+'|'+el.tabIndex); } } };
