const lum = ({r,g,b}) => { const f = v => { v/=255; return v<=0.03928? v/12.92 : Math.pow((v+0.055)/1.055,2.4); }; return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b); };
const cs = tag? getComputedStyle(tag):null;
return {ds, tag: tag? tag.outerHTML.replace(/ _ng[a-z]+-[a-z0-9-]+=""/g,'').slice(0,300):null, color: cs&&cs.color, bg: cs&&cs.backgroundColor, ratio: cs? +((Math.max(lum(parse(cs.color)),lum(parse(cs.backgroundColor)))+0.05)/(Math.min(lum(parse(cs.color)),lum(parse(cs.backgroundColor)))+0.05)).toFixed(2):null, rows: document.querySelector('tbody').rows.length, info: document.querySelector('.pagination-information').textContent.replace(/\s+/g,' ')};
}"}

